mapper.select:
select c.id, c.user_id, u.nickname, c.target_type, c.target_id, case when c.target_type = 'poi' then c.target_id when c.target_type = 'media' then m.poi_id else null end as related_poi_id, case when c.target_type = 'poi' then p.name when c.target_type = 'media' then concat('影像 #', c.target_id) else null end as target_name, c.content, c.review_status, c.reject_reason, c.create_time from `comment` c left join `user` u on u.id = c.user_id left join poi p on c.target_type = 'poi' and p.id = c.target_id left join media m on c.target_type = 'media' and m.id = c.target_id
and c.review_status = #{reviewStatus}
order by c.create_time desc limit #{limit}

select id, poi_id, type, image_path, year, description, upload_user_id, review_status, create_time from media where poi_id in
#{id}
order by poi_id asc, year desc, id desc
